// swiss design
// https://inspirationfeed.com/swiss-graphic-design
// https://inspirationfeed.com/wp-content/uploads/2017/03/43.jpg
// Première exposition du Collectif Instable

let objs;

function setup() {
  createCanvas(600, 600);

	objs = [];
	objs.push({x: 100, y: 100, r: 100, params: { p: 1 }});
	objs.push({x: 300, y: 100, r: 100, params: { p: 2 }});
	objs.push({x: 500, y: 100, r: 100, params: { p: 3, tf: -0.01 }});
	objs.push({x: 100, y: 300, r: 100, params: { p: 4 }});
	objs.push({x: 300, y: 300, r: 100, params: { p: 5, tf: -0.01 }});
	objs.push({x: 500, y: 300, r: 100, params: { p: 6 }});
	objs.push({x: 100, y: 500, r: 100, params: { p: 7, tf: -0.01 }});
	objs.push({x: 300, y: 500, r: 100, params: { p: 8 }});
	objs.push({x: 500, y: 500, r: 100, params: { p: 9 }});
}

function draw() {
  background(32);

	for (let o of objs) {
		pCircle(o.x, o.y, o.r, o.params);
	}
}

function pCircle(x, y, r, params) {
  let sw = params.sw || r / 20; // stroke weight
  let pa = params.p || -1; // pattern
  let tf = params.tf || 0.01; // time fraction

  // mask in shape
  push();
  clip(() => {
    circle(x, y, r + r);
    // rect(x - r, y - r, r + r, r + r)
  });

  noFill();
  stroke(196);
  strokeWeight(sw * 0.5);

  // patterns
  switch (pa) {
    case 1: 
      { // outer circles
        for (let cr = r - sw / 2; cr > 0; cr -= 1.41 * sw) {
          circle(x, y, cr + cr);
        }
      }
      break;

    case 2:
      { // star
        const u = TWO_PI * 2 * r;
        const n = u / sw / 2 / 2;
        const a = TWO_PI / n;
        translate(x, y);
        rotate(frameCount * tf);
        strokeWeight(sw * 0.5);
        for (let i = 0; i < n; i++) {
          line(0, 0, r, 0);
          rotate(a);
        }
      }
      break;

    case 3:
      { // diagonal lines
        translate(x, y);
        rotate(frameCount * tf);
        translate(-r, -r);
        strokeWeight(sw * 0.5);
        for (let i = 0; i <= r + r; i += sw + sw) {
          const l = r + r - i;
          line(i, 0, l + i, l);
          if (i) line(0, i, l, l + i);
        }
      }
      break;

    case 4:
      { // horiz + vert lines
        translate(x, y);
        rotate(frameCount * tf);
        translate(-r, -r);
        strokeWeight(sw * 0.5);
        for (let i = 0; i <= r + r; i += 1.41 * sw) {
          beginShape();
          vertex(0, i);
          vertex(r + r - i, i);
          vertex(r + r - i, r + r);
          endShape();
        }
      }
      break;

    case 5:
      { // zick zack lines
        const d = r * 0.25;
        translate(x, y);
        rotate(frameCount * tf);
        translate(-r, -r);
        strokeWeight(sw * 0.5);
        for (let i = -d; i <= r + r; i += sw + sw) {
          beginShape();
					for (let j = 0; j < 9; j++) {
	          vertex(j * d, i + (j % 2) * d);
					}
          endShape();
        }
      }
      break;

    case 6:
      { // dotted 1
        translate(x, y);
        rotate(frameCount * tf);
        translate(sw - r, sw - r);
        strokeWeight(sw);
        var n = (r / sw) * 2;
        for (let i = 0; i <= n; i++) {
          for (let j = 0; j <= n; j++) {
            if ((i + j) % 2) point(i * sw, j * sw);
          }
        }
      }
      break;

    case 7:
      { // dotted 2
        translate(x, y);
        rotate(frameCount * tf);
        translate(sw - r, sw - r);
        strokeWeight(sw);
        var n = r / sw;
        for (let i = 0; i <= n; i++) {
          for (let j = 0; j <= n; j++) {
            point(i * sw * 2, j * sw * 2);
          }
        }
      }
      break;

    case 8:
      { // dotted 3
        translate(x, y);
        rotate(frameCount * tf);
        translate(sw - r, sw - r);
        strokeWeight(sw);
        var n = r / sw;
        for (let i = 0; i <= n; i++) {
          for (let j = 0; j <= n; j++) {
            point(i * sw * 2, j * sw * 2 + (i % 2 ? 0 : sw));
          }
        }
      }
      break;

    default:
      circle(x, y, 2 * r - sw);
  }

  pop();
}
